localimage_explain: "يفتح الصورة كقرص عادي على هذا الحاسوب، فتستطيع إضافة الملفات داخلها واستبدالها وحذفها — ملفات الرقع مثلًا — باستخدام Finder أو مستكشف الملفات، تمامًا كما لو كانت ذاكرة USB. وتُحفظ التغييرات مباشرةً داخل ملف الصورة. ولا يكتب ps5upload في الصورة أبدًا؛ بل يقوم بذلك نظام التشغيل لديك. أخرِج الصورة من هنا عند الانتهاء.",
