"fpkg.image.folderOnly_v4": "لا يمكن أن يصبح صورة لعبة إلا مجلد لعبة أو صورة لعبة أو أرشيف (.zip أو .7z أو .rar) يحتوي على لعبة؛ يُفك الأرشيف أولًا في مجلد الإخراج.",
