connection_payload_engine_unreachable: "لم يتمكن التطبيق من الوصول إلى محركه الخاص على هذا الحاسوب، لذا لا يعرف إن كان المساعد قد بدأ على PS5. هذه ليست مشكلة في PS5: الإشعار أعلى النافذة يوضح السبب ويمكنه إعادة تشغيل المحرك. ثم اضغط «إرسال المساعد» مرة أخرى. ({error})",
"engine_problem.missing.fix": "استعد ps5upload-engine من عزل برنامج مكافحة الفيروسات (أو اسمح به)، أو أعد تثبيت التطبيق.",
