"profile.np.body": "يجعل PS5 يعامل الحساب المسجّل دخوله كأنه مسجّل في PlayStation Network، دون الاتصال بـ Sony. بعض ميزات الجهاز لا تُتاح إلا لحساب مسجّل الدخول، ومنها اللعب عن بُعد. يستخدم np-fake-signin من earthonion، ويُجلب من صفحة المشروع عند الضغط على الزر.",
