"pkg.sony_80b21104": "لم يقبل جهاز PS5 هذه الحزمة (0x80B21104). إن كانت حزم أخرى تُثبَّت على هذا الجهاز فالمشكلة في هذا الملف: غالبًا لعبة حديثة صُنعت حزمتها بأدوات أحدث مما يفهمه نظام هذا الجهاز، أو حزمة ليست إصدارًا بتوقيع مزيف (FPKG). استخدم حزمة مصنوعة لنظامك (backport)، أو ثبّت اللعبة بطريقة لا تمر بالمثبّت: انسخ مجلد اللعبة، أو صورة لعبة (.exfat أو .ffpfsc) لـ ShadowMount+، عبر رفع.",
