a11y_dyslexia_hint_v2: "يستخدم خط Atkinson Hyperlegible أو OpenDyslexic إذا كان أحدهما مثبتًا على هذا الجهاز (لا يأتي أيٌّ منهما مع التطبيق)، مع تباعد أوسع قليلًا بين الحروف والأسطر. وبدونهما يتغيّر التباعد فقط.",
