settings_updates_browser_note: "تُقدَّم صفحة الويب هذه من محرك ps5upload وتُحدَّث معه: اسحب صورة Docker الجديدة (أو حدّث المحرك على خادمك) وأعد تشغيله.",
"show_file_list_hint_v2": "اعرض الملفات التي يجري رفعها أسفل شريط التقدم. أطفئه إن بدت القائمة مزدحمة مع مجلدات فيها آلاف الملفات — سيظل التقدم الكلي والسرعة والوقت المتبقي ظاهرة.",
show_file_list_v2: "عرض قائمة الملفات أثناء الرفع",
stats_description_v2: "إجماليات العمليات المعروضة لهذا الجهاز. يحتفظ التطبيق بآخر {count}، لذا لا تُحتسب الأقدم. تُحسب من السجل المحلي؛ لا يغادر شيء جهازك.",
status_keep_awake_tooltip_v2: "إبقاء التشغيل مضبوط على «دائمًا أثناء الاتصال» — لن تدخل الأجهزة المتصلة وضع الراحة تلقائيًا طالما التطبيق مفتوح. غيّره من الإعدادات → الجهاز.",
update_idle_v2: "لم يتم التحقق بعد. مع تفعيل التحقق التلقائي، يبحث التطبيق في الخلفية عند التشغيل، مرة واحدة يوميًا على الأكثر.",
upload_auto_resume_hint_browser: "إذا انقطع الرفع أثناء النقل، يُستأنف من حيث توقف بمجرد أن يستجيب مساعد PS5 مجددًا، مع إعادة المحاولة بضع مرات قبل الاستسلام. لا تستطيع هذه الصفحة إعادة إرسال المساعد بنفسها: إذا أُعيد تشغيل PS5، أرسله مجددًا أولًا. المشكلات القاتلة مثل امتلاء مساحة PS5 تتوقف فورًا. مفعّل افتراضيًا.",
upload_wake_for_uploads: "إيقاظ PS5 من أجل رفع ينتظر",
upload_wake_for_uploads_hint: "عندما ينتظر رفعٌ جهاز PS5 في وضع الراحة، يُرسَل إليه إشارة إيقاظ ويستمر الرفع فور عودة المساعد. فقط للأجهزة التي أُعدّ لها الإيقاظ في شاشة الاتصال. مفعّل افتراضيًا.",
upload_picker_from_ps5_hint: "تنسخ من PS5 آخر؟ حدّد الملفات في «نظام الملفات» واختر «إرسال إلى جهاز آخر».",
