"minion_lan_label": "فتح Minion من أجهزة أخرى على شبكتك",
"minion_lan_hint": "متوقف: يفتحه متصفح PS5 نفسه فقط. مفعّل: يمكن لهاتف أو جهاز لوحي أو كمبيوتر على الشبكة نفسها فتحه أيضًا، أي أن أي شخص على تلك الشبكة يستطيع ذلك. فعّله في المنزل فقط.",
"minion_open_here": "فتح هنا",
"minion_remove_note": "الإزالة توقف Minion وتحذف ما يحتفظ به على PS5: مفضلات الملفات والمجلدات الأخيرة، وذاكرة المكتبة المؤقتة للألعاب، وسجل وحدة التحكم. تبقى مشاركات الشبكة والغشّات والنسخ الاحتياطية، فتطبيق الكمبيوتر يستخدمها أيضًا.",
