"minion_remove_confirm": "يُزال مربعه من الشاشة الرئيسية وصفحته، وتُحذف ملفاته الخاصة على PS5. يُبقيه المساعد متوقفًا من الآن فصاعدًا. يمكنك إعادة تشغيله من هنا في أي وقت.",
