"fs_drag_hint_move": "اسحب الملفات والمجلدات خارج النافذة لنسخها إلى هذا الكمبيوتر، أو اسحبها إلى الداخل لنسخها هنا. اضغط مع الاستمرار على Alt (⌥ Option على Mac) أثناء السحب لنقلها إلى مجلد هنا.",
"fs_drag_hint": "اسحب الملفات والمجلدات خارج النافذة لنسخها إلى هذا الكمبيوتر، أو اسحبها إلى الداخل لنسخها هنا.",
