"installed_uninstall_no_copy": "لا توجد في مجموعتك على هذا الكمبيوتر نسخة من هذه اللعبة: احتفظ بحزمتها في مكان ما قبل إلغاء التثبيت.",
"connection_send_payload_moved": "هل تريد إرسال حمولة أخرى (kstuff أو etaHEN أو أي ملف ‎.elf)؟ ستجد ذلك في الحمولات ← إرسال حمولة. هذه الشاشة ترسل مساعد PS5Upload فقط.",
"connection_send_payload_open": "فتح إرسال حمولة",
"upload_elf_title": "هذه حمولة (‎.elf) وليست لعبة",
"upload_elf_body": "رفعه ينسخ الملف فقط. يلتقط ShadowMount+‎ مجلدات الألعاب (التي تحتوي على eboot.bin وsce_sys) وصور الألعاب، ولا يلتقط ملف ‎.elf أبدًا، لذا لن يظهر على الشاشة الرئيسية. لتشغيله، أرسله إلى مُحمِّل الجهاز بدلًا من ذلك. ما يجب رفعه هو تطبيق homebrew يأتي كصورة ‎.ffpkg أو ‎.exfat، أو كمجلد يحتوي على eboot.bin.",
"netdoctor.hint.below_test": "يعمل هذا الرفع بسرعة {speed}، وهي أقل بكثير من {expected} التي قاسها اختبار السرعة.",
"netdoctor.hint.runs_at": "يعمل هذا الرفع بسرعة {speed}.",
"netdoctor.hint.cause_source": "ما يبطئه هو قراءة الملفات على هذا الكمبيوتر وليس الشبكة: محرك USB أو قرص صلب أو مجلد شبكة مشترك (NAS) أو فك ضغط أرشيف أبطأ من الاتصال. نسخ اللعبة إلى SSD داخلي أولًا، أو رفع ملفات الأرشيف بعد فك ضغطها، يعطي السرعة الكاملة.",
"netdoctor.hint.cause_disk": "ما يبطئه هو قرص PS5 وليس الشبكة: محرك USB خارجي، أو قرص ممتلئ تقريبًا، أو آلاف الملفات الصغيرة (لكل منها وقت خاص به) تكتب أبطأ مما يوصله الاتصال. صورة اللعبة (‎.ffpkg أو ‎.exfat) تُرسَل كملف واحد.",
"netdoctor.hint.cause_workers": "لا يزال PS5 يكتب ما استلمه، ولا ينتظر الشبكة. مع كثرة الملفات الصغيرة يستغرق كل منها وقتًا خاصًا به؛ أما صورة اللعبة (‎.ffpkg أو ‎.exfat) فتُرسَل كملف واحد.",
"netdoctor.hint.cause_cap": "ما يبطئه هو حد سرعة الرفع (نحو {cap} ميبيبايت/ث، في هذه الشاشة وفي الإعدادات). اضبطه على 0 لإزالته.",
"profile.np.confirm_body_v2": "يكتب np-fake-signin ملفات وإعدادات تسجيل الدخول إلى PlayStation Network للمستخدم {user} على PS5. لا يُرسل شيء إلى Sony. أعد تشغيل PS5 بعد ذلك.",
"profile.np.side_effect": "أثر جانبي معروف: بعد ذلك تطلب بعض الأجهزة «تعطيل قيود جهاز PS5 مؤقتًا» قبل فتح أي لعبة، وقد يبقى خيار الإعدادات > المستخدمون والحسابات > أخرى > تسجيل الخروج معطّلًا. يحتفظ التطبيق أولًا بنسخة من كل ما يغيّره np-fake-signin على PS5، لذا يعيده زر التراجع عن تسجيل الدخول هنا.",
"profile.np.backing_up": "جارٍ الاحتفاظ بنسخة من إعدادات الحساب الحالية على PS5…",
"profile.np.backup_failed": "تعذّر على PS5 الاحتفاظ بنسخة من إعدادات الحساب، لذا لم يُشغَّل np-fake-signin. استبدل المساعد بإصدار هذا التطبيق وحاول مجددًا. ({error})",
"profile.np.step_restart_v2": "أعد تشغيل PS5. للتراجع لاحقًا، اضغط «التراجع عن تسجيل الدخول» هنا ثم أعد التشغيل مجددًا.",
"profile.np.undo": "التراجع عن تسجيل الدخول",
"profile.np.undo_hint": "تُحفظ على PS5 نسخة من إعدادات هذا الحساب من قبل تسجيل الدخول؛ وهذا يعيدها.",
"profile.np.undo_confirm_title": "التراجع عن تسجيل الدخول؟",
"profile.np.undo_confirm_body": "يعيد إعدادات {user} وملفاته كما كانت قبل تشغيل np-fake-signin. أعد تشغيل PS5 بعد ذلك. قد تتوقف الميزات التي تحتاج إلى حساب مسجَّل الدخول، ومنها اللعب عن بُعد، عن الفتح حتى تسجّل الدخول مجددًا.",
"profile.np.undoing": "جارٍ إعادة الإعدادات…",
"profile.np.undone": "تمت الإعادة ({count} من الإعدادات والملفات). أعد تشغيل PS5 لإكمال العملية.",
"profile.np.no_backup": "يحمل هذا الحساب إعدادات القالب الخاصة بـ np-fake-signin (تاريخ الميلاد 1983-04-12، وعلامة البالغ دون اتصال مطفأة)، ولا توجد على هذا الـ PS5 نسخة من قبل، لذا لا يستطيع التطبيق التراجع عنها. إذا صار PS5 يطلب تعطيل قيود الجهاز مؤقتًا قبل فتح الألعاب: الإعدادات > العائلة والرقابة الأبوية > قيود جهاز PS5 (رمز المرور 0000 ما لم تغيّره)، وارفع القيود هناك.",
