"rpg_account_body": "يقترن اللعب عن بُعد بمعرّف حساب. المستخدم المرتبط بـ PlayStation Network لديه واحد بالفعل؛ أما المستخدم دون اتصال فيحتاج إلى تعيين واحد في «المستخدمون» أعلاه (أي معرّف يصلح؛ دوّنه، فالحفظ الذي يُنشأ بعد ذلك يرتبط به).",
"rpg_signin_title": "سجّل دخول الحساب إلى PlayStation Network (دون اتصال)",
"rpg_signin_body": "لا يسمح PS5 باستخدام اللعب عن بُعد إلا لحساب مسجّل الدخول. إذا كان إعداد اللعب عن بُعد في الجهاز نفسه معطّلًا (رماديًا)، فشغّل تسجيل الدخول دون اتصال أدناه (لا يُرسل شيء إلى Sony)، ثم أعد تشغيل PS5. يمكن التراجع عنه.",
"rpg_signin_fix": "انتقل إلى تسجيل الدخول",
"rpg_service_title": "شغّل اللعب عن بُعد",
"rpg_service_body": "الإعدادات › النظام › اللعب عن بُعد › تفعيل اللعب عن بُعد. يمكن للتطبيق تشغيله لك، كما يمكنه على البرنامج الثابت 10.00 وما بعده السماح به لهذا المستخدم أيضًا.",
"rpg_rest_title": "اسمح بإيقاظ PS5 من وضع الراحة",
"rpg_rest_body": "الإعدادات › النظام › توفير الطاقة › الميزات المتاحة في وضع الراحة: فعّل «البقاء متصلاً بالإنترنت» و«تفعيل تشغيل PS5 عبر الشبكة». بدونهما لا يمكن إيقاظ الجهاز من وضع الراحة، وتتوقف شبكته بعد بضع ثوانٍ. لا يعرض هذه الإعدادات إلا الجهاز نفسه.",
"rpg_pair_title": "اقرن هذا التطبيق بالجهاز",
"rpg_pair_body": "الاتصال › تشغيل وتسجيل دخول › إعداد. نقرة واحدة تسجّل هذا التطبيق لدى PS5 (مثل إقران تطبيق PS Remote Play) وتحفظ مفاتيحه على هذا الكمبيوتر. يستخدمها البث والإيقاظ وتسجيل الدخول كلها؛ أعد ذلك بعد إعادة ضبط الجهاز أو تغيير المستخدم.",
"rpg_play_title": "العب",
"rpg_play_body": "افتح «اللعب عن بُعد» واضغط «ابدأ»: يوقظ التطبيق الجهاز إن كان في وضع الراحة، ويسجّل الدخول، ويبدأ البث. العب بيد تحكم موصولة بهذا الكمبيوتر أو بلوحة المفاتيح أو باللمس. لاستخدام تطبيق PS Remote Play من Sony أو chiaki-ng بدلًا من ذلك، اطلب PIN أدناه وأدخله هناك.",
"rpg_play_fix": "افتح اللعب عن بُعد",
"rpg_title": "إعداد اللعب عن بُعد",
"rpg_progress": "اكتملت {done} من {n} من الخطوات المفحوصة",
"rpg_on_console": "تحقّق على الجهاز",
"rpg_trouble": "إن لم يعمل بعد",
"rpg_t_start_q": "زر ابدأ رمادي في شاشة «العب».",
"rpg_t_start_a": "هذا التطبيق غير مقترن بذلك الجهاز بعد: نفّذ الخطوة 6 (الاتصال › تشغيل وتسجيل دخول › إعداد).",
"rpg_t_pair_q": "يقول إعداد الإقران إنه لا يوجد مستخدم مسجّل الدخول بحساب مفعّل.",
"rpg_t_pair_a": "الخطوتان 1 و2: سجّل الدخول إلى مستخدم على PS5 وامنحه معرّف حساب، ثم حاول مجددًا.",
"rpg_t_grey_q": "إعداد اللعب عن بُعد في PS5 نفسه معطّل (رمادي).",
"rpg_t_grey_a": "الحساب غير مسجّل الدخول إلى PlayStation Network. شغّل تسجيل الدخول دون اتصال (الخطوة 3) وأعد تشغيل PS5.",
"rpg_t_wake_q": "الجهاز لا يستيقظ، أو يستيقظ لكنه يبقى على شاشة المستخدم.",
"rpg_t_wake_a": "تحقّق من الخطوة 5 على الجهاز. المستخدم الذي لديه رمز دخول يوقف تسجيل الدخول التلقائي. إذا أُعيد ضبط الجهاز أو تغيّر المستخدم، فأعد إعداد الإقران (الخطوة 6).",
"rpg_t_black_q": "تبقى الصورة سوداء، أو تتقطع، أو يطقطق الصوت.",
"rpg_t_black_a": "استخدم اتصالًا سلكيًا أو 5 GHz Wi-Fi لـ PS5 ولهذا الكمبيوتر، وجرّب 720p أو 30 fps في إعدادات اللعب عن بُعد. يجب أن يسمح جدار الحماية على هذا الكمبيوتر للتطبيق بالعمل على الشبكة المحلية (يستخدم اللعب عن بُعد منافذ TCP وUDP من 9295–9304). في المتصفح، استخدم إصدارًا حديثًا من Chrome أو Edge أو Safari: فالصورة تحتاج إلى WebCodecs.",
"rpg_t_busy_q": "تظهر رسالة بأن PS5 لا يزال يُنهي الجلسة الأخيرة، أو أن جهازًا آخر يبث.",
"rpg_t_busy_a": "يبث جهاز واحد في كل مرة، ويحتاج PS5 إلى ما يصل إلى 30 ثانية بعد انتهاء الجلسة. أوقف البث الآخر، وانتظر قليلًا، ثم اضغط «ابدأ» مجددًا.",
"rpg_t_restrict_q": "بعد تسجيل الدخول دون اتصال، تطلب الألعاب تعطيل قيود الجهاز.",
"rpg_t_restrict_a": "استخدم «التراجع عن تسجيل الدخول» في هذه الصفحة وأعد التشغيل، أو ارفع القيود من الإعدادات › العائلة والرقابة الأبوية › قيود جهاز PS5 (رمز المرور 0000 ما لم تغيّره).",
