"rp_other_device_playing_body": "يشغّل PS5 اللعب عن بُعد مع جهاز واحد فقط في كل مرة: البدء هنا ينهيه هناك.",
"mesh_rp_started": "بدأ {name} اللعب على هذا الجهاز",
"rp_keys_body3": "انقر على الصورة للعب بلوحة المفاتيح؛ يعيد Esc المؤشر. انقر مرتين لملء الشاشة؛ هناك ضغطة قصيرة على Esc هي الدائرة، والضغط المطوّل على Esc يخرج من ملء الشاشة. المفاتيح والصوت والمزيد في الإعدادات.",
"rp_play_description2": "بُثّ جهاز PS5 إلى هذا التطبيق والعب بوحدة تحكم أو لوحة المفاتيح أو اللمس. يوقظ الجهاز من وضع الراحة تلقائيًا، ويستمر اللعب أثناء استخدامك شاشات أخرى.",
