"dump_decrypt_risk_body": "لفك التشفير، يستبدل المساعد مؤقتاً جزءاً من النظام تستخدمه كل البرامج لكل ملف تنفيذي. إذا قرأت اللعبة ملفاً في تلك اللحظة فقد يتجمد الجهاز ويحتاج إلى إطفاء قسري. ابقَ على شاشة بدء اللعبة أثناء العملية. البرنامج الثابت حتى 13.60 فقط؛ على الإصدارات الأحدث يكون التفريغ نسخة عادية.",
