"send_title_v2": "الرفع والتثبيت",
"collection.send_many_body_v2": "يحصل كل PS5 على ما ينقصه: حزمة اللعبة، أو مجلدها أو صورتها أو أرشيفها، إضافةً إلى التحديثات الأحدث ومحتوى DLC للألعاب التي لديه. تُبث الحزم من هذا الحاسوب؛ ويُرفع الباقي إلى محرك الأقراص المحدد في «الرفع والتثبيت»، داخل مجلد homebrew.",
"first_run_step4_body_v3": "أدخل ذاكرة USB تحتوي على صور ألعاب .ffpkg في جهاز PS5 وسيركّبها ShadowMount+ تلقائيًا — ستظهر في «الألعاب». لإرسال ملفات أخرى أو تثبيت حزم .pkg، استخدم «الرفع والتثبيت».",
"first_run_go_upload_v2": "افتح «الرفع والتثبيت»",
"fpkg.aboutFake_v2": "الناتج حزمة مزيفة، لذا يحتاج الجهاز إلى تحميل دعم الحزم المزيفة قبل تثبيتها: kstuff (الإصدار الذي يدعم حزم PS5 المزيفة) وa53_ppr_install_fast.elf وshadowmountplus.elf، بهذا الترتيب. تذكر صفحة «الرفع والتثبيت» الأمر نفسه بجوار أزرار التثبيت.",
"fpkg.openUpload_v2": "افتح «الرفع والتثبيت»",
"connection_step3_hint_v3": "افتح «الرفع والتثبيت» وأفلت مجلد لعبة أو صورة .exfat أو .ffpkg أو حزمة .pkg. تظهر الصور والمجلدات التي ترسلها في صفحة اللعبة ضمن «الألعاب»، حيث يضعها «تثبيت» على الشاشة الرئيسية لـ PS5.",
